# Each beat: gap, months, on, needs, kind, to, from_ru, from_en, brief_ru, brief_en, news_ru, news_en, reply, gift, stamp, sets
ARCS = {}


def arc(name, *beats):
    ARCS[name] = beats


# Pace: per-arc factor on the written gaps, tuned so each arc takes about two years.
SCALE = {"matvei": 0.9, "irina": 0.9, "gleb": 0.75, "belkin_school": 1.0, "belkin_wood": 0.8, "pavel": 0.9, "sofia": 0.8}


def b(gap, months, kind, to, frm, brief, news, *, on="", needs="", reply="", gift="", stamp="", sets=""):
    return (gap, months, on, needs, kind, to, frm[0], frm[1], brief[0], brief[1], news[0], news[1], reply, gift, stamp, sets)


