COLS = ["arc", "n", "gap", "months", "on", "needs", "kind", "to", "from_ru", "from_en", "brief_ru", "brief_en",
        "news_ru", "news_en", "reply", "gift", "stamp", "sets"]


def clean(v):
    v = str(v)
    assert "\t" not in v and "\n" not in v and "\r" not in v, v
    return v


def write(path, header, rows):
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = ["\t".join(header)] + ["\t".join(clean(c) for c in r) for r in rows]
    path.write_bytes(("\n".join(lines) + "\n").encode("utf-8"))


def main():
    rows = []
    for name, beats in ARCS.items():
        for n, beat in enumerate(beats, start=1):
            gap = max(3, round(beat[0] * SCALE[name]))
            rows.append((name, n, gap, *beat[1:]))
    write(C / "arcs/d.tsv", COLS, rows)
    write(C / "items/d.tsv", ["key", "family", "variant", "name_ru", "name_en"], ITEMS)
    write(C / "stamps/d.tsv", ["key", "family", "bg", "value", "name_ru", "name_en", "series"], STAMPS)
    print(f"{len(rows)} beats, {len(ITEMS)} items, {len(STAMPS)} stamps")


if __name__ == "__main__":
    main()
